{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "header_stack",
        "intro_text",
        "section_title",
        "fellowship_card",
        "two_towers_card",
        "return_king_card"
      ]
    },
    "header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "book_icon",
        "main_title"
      ]
    },
    "book_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000869_01_1_book.svg"
      },
      "children": []
    },
    "main_title": {
      "type": "Text",
      "props": {
        "text": "The Lord of the Rings: Core Narrative Overview",
        "variant": "h1"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "J.R.R. Tolkien's The Lord of the Rings is an epic high-fantasy saga detailing the quest to destroy the One Ring, an evil artifact created by the Dark Lord Sauron. The narrative follows a fellowship of diverse characters as they journey across Middle-earth, facing immense challenges and personal growth, ultimately determining the fate of their world.",
        "variant": "body"
      },
      "children": []
    },
    "section_title": {
      "type": "Text",
      "props": {
        "text": "Book-by-Book Journey and Key Character Developments",
        "variant": "h2"
      },
      "children": []
    },
    "fellowship_card": {
      "type": "Card",
      "props": {},
      "children": [
        "fellowship_content_stack"
      ]
    },
    "fellowship_content_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "fellowship_title",
        "fellowship_plot_label",
        "fellowship_plot_stack",
        "fellowship_arcs_label",
        "fellowship_arcs_stack"
      ]
    },
    "fellowship_title": {
      "type": "Text",
      "props": {
        "text": "The Fellowship of the Ring",
        "variant": "h3"
      },
      "children": []
    },
    "fellowship_plot_label": {
      "type": "Text",
      "props": {
        "text": "Main Plot Points:",
        "variant": "label"
      },
      "children": []
    },
    "fellowship_plot_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "fellowship_plot_1",
        "fellowship_plot_2",
        "fellowship_plot_3",
        "fellowship_plot_4",
        "fellowship_plot_5",
        "fellowship_plot_6",
        "fellowship_plot_7",
        "fellowship_plot_8"
      ]
    },
    "fellowship_plot_1": {
      "type": "Text",
      "props": {
        "text": "Frodo Baggins inherits a mysterious ring from his uncle Bilbo.",
        "variant": "body"
      },
      "children": []
    },
    "fellowship_plot_2": {
      "type": "Text",
      "props": {
        "text": "Gandalf the wizard reveals it to be the One Ring of Sauron and tasks Frodo with its destruction.",
        "variant": "body"
      },
      "children": []
    },
    "fellowship_plot_3": {
      "type": "Text",
      "props": {
        "text": "Frodo, accompanied by Samwise Gamgee, Merry Brandybuck, and Pippin Took, flees the Shire, pursued by the Nazgûl (Ringwraiths).",
        "variant": "body"
      },
      "children": []
    },
    "fellowship_plot_4": {
      "type": "Text",
      "props": {
        "text": "They meet Aragorn (Strider) and eventually reach Rivendell.",
        "variant": "body"
      },
      "children": []
    },
    "fellowship_plot_5": {
      "type": "Text",
      "props": {
        "text": "The Council of Elrond decides the Ring must be destroyed in the fires of Mount Doom in Mordor, and the Fellowship of the Ring is formed.",
        "variant": "body"
      },
      "children": []
    },
    "fellowship_plot_6": {
      "type": "Text",
      "props": {
        "text": "The Fellowship's journey through Moria leads to Gandalf's apparent death in a battle with a Balrog.",
        "variant": "body"
      },
      "children": []
    },
    "fellowship_plot_7": {
      "type": "Text",
      "props": {
        "text": "After a stay in Lothlórien, the Fellowship is attacked at Amon Hen, where Boromir is corrupted by the Ring and falls defending Merry and Pippin, who are captured by Orcs.",
        "variant": "body"
      },
      "children": []
    },
    "fellowship_plot_8": {
      "type": "Text",
      "props": {
        "text": "Frodo and Sam decide to continue their quest alone towards Mordor.",
        "variant": "body"
      },
      "children": []
    },
    "fellowship_arcs_label": {
      "type": "Text",
      "props": {
        "text": "Key Character Arcs:",
        "variant": "label"
      },
      "children": []
    },
    "fellowship_arcs_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "fellowship_arc_frodo",
        "fellowship_arc_samwise",
        "fellowship_arc_aragorn",
        "fellowship_arc_gandalf",
        "fellowship_arc_boromir"
      ]
    },
    "fellowship_arc_frodo": {
      "type": "Text",
      "props": {
        "text": "Frodo: Transforms from a comfortable hobbit into the burdened Ring-bearer, accepting a perilous destiny.",
        "variant": "body"
      },
      "children": []
    },
    "fellowship_arc_samwise": {
      "type": "Text",
      "props": {
        "text": "Samwise: Begins as a loyal gardener, growing in courage and devotion as he commits to Frodo's aid.",
        "variant": "body"
      },
      "children": []
    },
    "fellowship_arc_aragorn": {
      "type": "Text",
      "props": {
        "text": "Aragorn: Introduced as a mysterious Ranger, he starts to embrace his true identity as the heir to Gondor's throne, displaying nascent leadership.",
        "variant": "body"
      },
      "children": []
    },
    "fellowship_arc_gandalf": {
      "type": "Text",
      "props": {
        "text": "Gandalf: Acts as a wise mentor and guide, sacrificing himself for the Fellowship, hinting at a deeper purpose.",
        "variant": "body"
      },
      "children": []
    },
    "fellowship_arc_boromir": {
      "type": "Text",
      "props": {
        "text": "Boromir: A noble warrior, he struggles with the Ring's temptation, ultimately finding redemption through his brave sacrifice.",
        "variant": "body"
      },
      "children": []
    },
    "two_towers_card": {
      "type": "Card",
      "props": {},
      "children": [
        "two_towers_content_stack"
      ]
    },
    "two_towers_content_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "two_towers_title",
        "two_towers_plot_label",
        "two_towers_plot_stack",
        "two_towers_arcs_label",
        "two_towers_arcs_stack"
      ]
    },
    "two_towers_title": {
      "type": "Text",
      "props": {
        "text": "The Two Towers",
        "variant": "h3"
      },
      "children": []
    },
    "two_towers_plot_label": {
      "type": "Text",
      "props": {
        "text": "Main Plot Points:",
        "variant": "label"
      },
      "children": []
    },
    "two_towers_plot_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "two_towers_plot_hunters_label",
        "two_towers_plot_hunters_1",
        "two_towers_plot_hunters_2",
        "two_towers_plot_hunters_3",
        "two_towers_plot_ringbearers_label",
        "two_towers_plot_ringbearers_1",
        "two_towers_plot_ringbearers_2",
        "two_towers_plot_ringbearers_3",
        "two_towers_plot_merrypippin_label",
        "two_towers_plot_merrypippin_1"
      ]
    },
    "two_towers_plot_hunters_label": {
      "type": "Text",
      "props": {
        "text": "The Hunters:",
        "variant": "label"
      },
      "children": []
    },
    "two_towers_plot_hunters_1": {
      "type": "Text",
      "props": {
        "text": "Aragorn, Legolas, and Gimli pursue the Orcs who captured Merry and Pippin, eventually meeting Gandalf, now Gandalf the White, who is more powerful and purposeful.",
        "variant": "body"
      },
      "children": []
    },
    "two_towers_plot_hunters_2": {
      "type": "Text",
      "props": {
        "text": "They travel to Rohan, where they help King Théoden break free from Saruman's influence and prepare for war.",
        "variant": "body"
      },
      "children": []
    },
    "two_towers_plot_hunters_3": {
      "type": "Text",
      "props": {
        "text": "The great Battle of Helm's Deep takes place, where the forces of Rohan, aided by Aragorn and Gandalf, defeat Saruman's Uruk-hai army.",
        "variant": "body"
      },
      "children": []
    },
    "two_towers_plot_ringbearers_label": {
      "type": "Text",
      "props": {
        "text": "The Ring-bearers:",
        "variant": "label"
      },
      "children": []
    },
    "two_towers_plot_ringbearers_1": {
      "type": "Text",
      "props": {
        "text": "Frodo and Sam continue their arduous journey through treacherous lands, eventually capturing Gollum, who reluctantly agrees to guide them.",
        "variant": "body"
      },
      "children": []
    },
    "two_towers_plot_ringbearers_2": {
      "type": "Text",
      "props": {
        "text": "They encounter Faramir, Boromir's brother, in Ithilien, who resists the Ring's temptation and allows them to proceed.",
        "variant": "body"
      },
      "children": []
    },
    "two_towers_plot_ringbearers_3": {
      "type": "Text",
      "props": {
        "text": "Gollum leads them to the treacherous pass of Cirith Ungol, where Frodo is ambushed and poisoned by the giant spider Shelob. Sam believes Frodo dead and takes the Ring.",
        "variant": "body"
      },
      "children": []
    },
    "two_towers_plot_merrypippin_label": {
      "type": "Text",
      "props": {
        "text": "Merry & Pippin:",
        "variant": "label"
      },
      "children": []
    },
    "two_towers_plot_merrypippin_1": {
      "type": "Text",
      "props": {
        "text": "Escape their Orc captors and encounter Treebeard and the Ents in Fangorn Forest. They rouse the Ents to war, leading to the destruction of Saruman's fortress of Isengard.",
        "variant": "body"
      },
      "children": []
    },
    "two_towers_arcs_label": {
      "type": "Text",
      "props": {
        "text": "Key Character Arcs:",
        "variant": "label"
      },
      "children": []
    },
    "two_towers_arcs_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "two_towers_arc_frodo",
        "two_towers_arc_samwise",
        "two_towers_arc_aragorn",
        "two_towers_arc_gandalf",
        "two_towers_arc_merrypippin",
        "two_towers_arc_gollum"
      ]
    },
    "two_towers_arc_frodo": {
      "type": "Text",
      "props": {
        "text": "Frodo: The Ring's burden weighs heavily, showing his immense endurance but also increasing vulnerability to its influence.",
        "variant": "body"
      },
      "children": []
    },
    "two_towers_arc_samwise": {
      "type": "Text",
      "props": {
        "text": "Samwise: His loyalty intensifies, taking on the Ring temporarily and demonstrating his steadfast courage and protective nature.",
        "variant": "body"
      },
      "children": []
    },
    "two_towers_arc_aragorn": {
      "type": "Text",
      "props": {
        "text": "Aragorn: Fully steps into his role as a leader and potential king, inspiring hope and rallying the people of Rohan.",
        "variant": "body"
      },
      "children": []
    },
    "two_towers_arc_gandalf": {
      "type": "Text",
      "props": {
        "text": "Gandalf: Reborn as Gandalf the White, he becomes a more potent force for good, guiding and empowering the free peoples.",
        "variant": "body"
      },
      "children": []
    },
    "two_towers_arc_merrypippin": {
      "type": "Text",
      "props": {
        "text": "Merry & Pippin: Grow significantly from naive hobbits into brave and resourceful individuals, playing crucial roles in the defeat of Saruman.",
        "variant": "body"
      },
      "children": []
    },
    "two_towers_arc_gollum": {
      "type": "Text",
      "props": {
        "text": "Gollum: His internal struggle between his Smeagol and Gollum personalities is explored, driven by his obsessive desire for the Ring.",
        "variant": "body"
      },
      "children": []
    },
    "return_king_card": {
      "type": "Card",
      "props": {},
      "children": [
        "return_king_content_stack"
      ]
    },
    "return_king_content_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "return_king_title",
        "return_king_plot_label",
        "return_king_plot_stack",
        "return_king_arcs_label",
        "return_king_arcs_stack"
      ]
    },
    "return_king_title": {
      "type": "Text",
      "props": {
        "text": "The Return of the King",
        "variant": "h3"
      },
      "children": []
    },
    "return_king_plot_label": {
      "type": "Text",
      "props": {
        "text": "Main Plot Points:",
        "variant": "label"
      },
      "children": []
    },
    "return_king_plot_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "return_king_plot_war_label",
        "return_king_plot_war_1",
        "return_king_plot_war_2",
        "return_king_plot_war_3",
        "return_king_plot_war_4",
        "return_king_plot_end_label",
        "return_king_plot_end_1",
        "return_king_plot_end_2",
        "return_king_plot_end_3",
        "return_king_plot_end_4",
        "return_king_plot_aftermath_label",
        "return_king_plot_aftermath_1",
        "return_king_plot_aftermath_2",
        "return_king_plot_aftermath_3"
      ]
    },
    "return_king_plot_war_label": {
      "type": "Text",
      "props": {
        "text": "The War for Middle-earth:",
        "variant": "label"
      },
      "children": []
    },
    "return_king_plot_war_1": {
      "type": "Text",
      "props": {
        "text": "Gandalf and Pippin go to Minas Tirith, the capital of Gondor, to warn Denethor, the Steward.",
        "variant": "body"
      },
      "children": []
    },
    "return_king_plot_war_2": {
      "type": "Text",
      "props": {
        "text": "Aragorn, Legolas, and Gimli take the Paths of the Dead to summon the Army of the Dead, fulfilling an ancient prophecy.",
        "variant": "body"
      },
      "children": []
    },
    "return_king_plot_war_3": {
      "type": "Text",
      "props": {
        "text": "The Battle of the Pelennor Fields takes place outside Minas Tirith, where the forces of Gondor and Rohan, led by Théoden and Éowyn, fight against Sauron's armies.",
        "variant": "body"
      },
      "children": []
    },
    "return_king_plot_war_4": {
      "type": "Text",
      "props": {
        "text": "Aragorn reveals himself as the rightful King of Gondor and leads the forces of Men against Sauron's Black Gate as a diversion.",
        "variant": "body"
      },
      "children": []
    },
    "return_king_plot_end_label": {
      "type": "Text",
      "props": {
        "text": "The End of the Quest:",
        "variant": "label"
      },
      "children": []
    },
    "return_king_plot_end_1": {
      "type": "Text",
      "props": {
        "text": "Frodo and Sam, guided by Gollum, reach Mount Doom.",
        "variant": "body"
      },
      "children": []
    },
    "return_king_plot_end_2": {
      "type": "Text",
      "props": {
        "text": "At the Crack of Doom, Frodo succumbs to the Ring's power and claims it for himself.",
        "variant": "body"
      },
      "children": []
    },
    "return_king_plot_end_3": {
      "type": "Text",
      "props": {
        "text": "Gollum attacks Frodo, bites off his finger to reclaim the Ring, and falls into the fires of Mount Doom with the Ring, destroying it.",
        "variant": "body"
      },
      "children": []
    },
    "return_king_plot_end_4": {
      "type": "Text",
      "props": {
        "text": "Sauron's power is broken, and his armies are defeated.",
        "variant": "body"
      },
      "children": []
    },
    "return_king_plot_aftermath_label": {
      "type": "Text",
      "props": {
        "text": "Aftermath and Departure:",
        "variant": "label"
      },
      "children": []
    },
    "return_king_plot_aftermath_1": {
      "type": "Text",
      "props": {
        "text": "Aragorn is crowned King Elessar of the Reunited Kingdom.",
        "variant": "body"
      },
      "children": []
    },
    "return_king_plot_aftermath_2": {
      "type": "Text",
      "props": {
        "text": "The hobbits return to the Shire and lead the Scouring of the Shire, restoring it from Saruman's corruption.",
        "variant": "body"
      },
      "children": []
    },
    "return_king_plot_aftermath_3": {
      "type": "Text",
      "props": {
        "text": "Years later, Frodo, Gandalf, Elrond, and Galadriel, accompanied by Bilbo, depart Middle-earth for the Undying Lands.",
        "variant": "body"
      },
      "children": []
    },
    "return_king_arcs_label": {
      "type": "Text",
      "props": {
        "text": "Key Character Arcs:",
        "variant": "label"
      },
      "children": []
    },
    "return_king_arcs_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "return_king_arc_frodo",
        "return_king_arc_samwise",
        "return_king_arc_aragorn",
        "return_king_arc_gandalf",
        "return_king_arc_merrypippin",
        "return_king_arc_gollum"
      ]
    },
    "return_king_arc_frodo": {
      "type": "Text",
      "props": {
        "text": "Frodo: Completes his quest, but is permanently scarred by the Ring's burden, leading to his departure from Middle-earth.",
        "variant": "body"
      },
      "children": []
    },
    "return_king_arc_samwise": {
      "type": "Text",
      "props": {
        "text": "Samwise: Remains steadfast and loyal, becoming a hero in his own right, and eventually returns to the Shire to live a full life.",
        "variant": "body"
      },
      "children": []
    },
    "return_king_arc_aragorn": {
      "type": "Text",
      "props": {
        "text": "Aragorn: Fully embraces his destiny as King, uniting the realms of Men and ushering in a new era of peace.",
        "variant": "body"
      },
      "children": []
    },
    "return_king_arc_gandalf": {
      "type": "Text",
      "props": {
        "text": "Gandalf: His mission complete, he departs Middle-earth, having guided the free peoples to victory.",
        "variant": "body"
      },
      "children": []
    },
    "return_king_arc_merrypippin": {
      "type": "Text",
      "props": {
        "text": "Merry & Pippin: Become Knights of Rohan and Gondor respectively, demonstrating their growth into brave and respected individuals.",
        "variant": "body"
      },
      "children": []
    },
    "return_king_arc_gollum": {
      "type": "Text",
      "props": {
        "text": "Gollum: His obsession with the Ring ultimately leads to its destruction and his own demise, fulfilling his role as an unwitting instrument of fate.",
        "variant": "body"
      },
      "children": []
    }
  }
}
